track: mem.Tracking_Allocator
mem.tracking_allocator_init(&track, context.allocator)
context.allocator = mem.tracking_allocator(&track)
// ... program runs ...
for _, leak in track.allocation_map {
  fmt.printf("%v leaked %v bytes\n", leak.location, leak.size)
}
peak := track.peak_memory_allocated

// Wrap a heap allocator with tracking
heap_alloc: mem.Allocator = mem.heap_allocator() 
track: mem.Tracking_Allocator
mem.tracking_allocator_init(&track, heap_alloc)
context.allocator = mem.tracking_allocator(&track)
// All allocations now go through tracking_allocator_proc, which logs via Tracking_Allocator_Entry

// Per-frame memory tracking
for frame in 1..100 {
  mem.tracking_allocator_clear(&track)
  // Frame's allocations happen here
  frame_peak := track.peak_memory_allocated
  fmt.printf("Frame %v peak: %v bytes\n", frame, frame_peak)
}

track.bad_free_callback = mem.tracking_allocator_bad_free_callback_add_to_array
// ... run code ...
for bad_free in track.bad_free_array {
  fmt.printf("Bad free of %p at %s:%v\n", bad_free.memory, bad_free.location.file_path, bad_free.location.line)
}

